import sys
import io
import typing
from typing import reveal_type

class FromWitness:
    pass

obj = FromWitness()

def current():
    if sys.argv[1] == 'core':
        assert reveal_type(obj) is obj
        print('identity')

    if sys.argv[1] == 'metadata':
        fn = reveal_type
        other = typing.reveal_type
        assert fn is other
        params = fn.__type_params__
        assert len(params) == 1
        t = params[0]
        assert isinstance(t, typing.TypeVar)
        assert t.__name__ == 'T'
        assert t is not typing.T
        assert t.__infer_variance__ is True
        assert fn.__annotations__ == {'obj': t, 'return': t}
        print('metadata')

    if sys.argv[1] == 'arguments':

        try:
            reveal_type(obj=obj)
        except TypeError:
            print('positional-only')
        else:
            raise AssertionError("accepted keyword obj")

    if sys.argv[1] == 'redirect':


        captured = io.StringIO()
        saved = sys.stderr
        try:
            sys.stderr = captured
            assert reveal_type(obj) is obj
            assert captured.getvalue() == "Runtime type is 'FromWitness'\n"
        finally:
            sys.stderr = saved
        print('redirected')

    if sys.argv[1] == 'broken':


        failure = RuntimeError("write failed")

        class BrokenStream:
            def write(self, text):
                raise failure

        saved = sys.stderr
        try:
            sys.stderr = BrokenStream()
            try:
                reveal_type(obj)
            except RuntimeError as error:
                assert error is failure
            else:
                raise AssertionError("lost stderr write failure")
        finally:
            sys.stderr = saved
        print('propagated')

    if sys.argv[1] == 'negative':
        assert reveal_type(obj) is not obj

