import unittest
from test.test_typing import RevealTypeTests

class Result(unittest.TestResult):
    def startTest(self, test):
        print('START',test.id(),flush=True)
        super().startTest(test)
    def addSuccess(self, test):
        print('PASS',test.id(),flush=True)
        super().addSuccess(test)
    def addSkip(self, test, reason):
        print('SKIP',test.id(),repr(reason),flush=True)
        super().addSkip(test,reason)
    def addFailure(self, test, err):
        print('FAIL',test.id(),repr(err[1]),flush=True)
        super().addFailure(test,err)
    def addError(self, test, err):
        print('ERROR',test.id(),repr(err[1]),flush=True)
        super().addError(test,err)
def current():
    case=RevealTypeTests("test_reveal_type")
    result=Result()
    case.run(result)
    assert result.testsRun==1 and result.wasSuccessful() and len(result.skipped)==0
